with remaining_keys as (select id, city from stores except distinct select id, city from stores where sqft between 5232 and 11992), reconciled as (select s.* from stores s join remaining_keys k on s.id = k.id and s.city = k.city) select store_name, city, opened_date, sqft, case when city rlike '^(Berlin|New York)$' then 'GROUP_B' when city rlike '^(Bangkok|Chiang Mai)$' then 'GROUP_A' else 'EXTENDED' end as city_zone from reconciled order by city nulls first
